import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const s="/bilder/timing.jpg",c=JSON.parse('{"title":"Timing","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/timing.md","filePath":"bereiche/timing.md"}'),a={name:"bereiche/timing.md"};function d(l,e,o,u,g,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h1><p>In einem Paket muss die SEAD vor dem Strike am Ziel sein, die CAP muss stehen, bevor der Tanker ankommt. Im Bereich Timing hängst du alle Flights an <strong>eine</strong> Bezugszeit – die <strong>H-Hour</strong> – und siehst sofort, ob die Routen dazu passen.</p><p><img src="'+s+'" alt="Sync-Matrix mit H-Hour, DEAD-Fenster, CAP und Tanker, darunter Editor und Wegpunkt-Tabelle" loading="lazy"></p><h2 id="so-funktioniert-es" tabindex="-1">So funktioniert es <a class="header-anchor" href="#so-funktioniert-es" aria-label="Permalink to &quot;So funktioniert es&quot;">​</a></h2><ol class="steps"><li><b>H-Hour setzen</b> – der Bezugspunkt des Pakets, meist der TOT des ersten Strikers. Alle Zeiten hängen an H; verschiebst du H, wandert das ganze Paket mit.</li><li><b>Flights hinzufügen</b> – unter <i>Ohne Timing</i> einen Flight anklicken, oder <b>Alle hinzufügen</b>.</li><li><b>Auftrag wählen</b> – <b>TOT</b> mit Fenster für Striker, <b>Vul</b> für CAP, Escort und Tanker, <b>SEAD/DEAD-Fenster</b> für die Weasels (DEAD geht auch als <b>DEAD-TOT</b>, z. B. ein Strike auf eine SAM-Stellung zu einer festen Zeit). Zeiten relativ zu H, z. B. <code>H-10</code> bis <code>H+15</code>.</li><li><b>Push- und Zielpunkt</b> aus der Route wählen. Die Matrix vergleicht mit den ETAs der Route und zeigt, wer zu früh oder zu spät ist.</li></ol><h2 id="die-sync-matrix" tabindex="-1">Die Sync-Matrix <a class="header-anchor" href="#die-sync-matrix" aria-label="Permalink to &quot;Die Sync-Matrix&quot;">​</a></h2><p>Oben eine Zeitachse, relativ zu H und als Uhrzeit. Jeder Flight ist eine Zeile, gruppiert nach Rolle:</p><table tabindex="0"><thead><tr><th>Zeichen</th><th>Bedeutung</th></tr></thead><tbody><tr><td>grauer Balken</td><td>Anlassen und Taxi bis Abheben (rückwärts gerechnet)</td></tr><tr><td>farbiger Balken</td><td>TOT-Fenster, Vul oder SEAD-Fenster</td></tr><tr><td>⚑</td><td>Push</td></tr><tr><td>gelbe Raute mit Name</td><td>Zeit an einem <a href="./zeichnungen#planungspunkte">Planungspunkt</a>, z. B. <em>MARSHAL ALPHA</em></td></tr><tr><td>graue Raute</td><td>weitere Sollzeit ohne Planungspunkt (Name beim Darüberfahren)</td></tr><tr><td>dünne Linie mit Nummern</td><td>Route mit Steerpoints (aus der Cartridge, sonst aus der Mission)</td></tr><tr><td>●</td><td>Ankunft am Zielpunkt laut Route – rot, wenn außerhalb des Fensters</td></tr><tr><td>gestrichelte Linie</td><td>Abstand zwischen nötigem Start und Start im Mission Editor</td></tr><tr><td>rot schraffiert</td><td>zu nahe an einem anderen Flight</td></tr></tbody></table><p>Senkrechte Linien markieren H, Sonnenauf- und -untergang.</p><p><strong>Bedienen:</strong> Fenster ziehen verschiebt die Zeiten (rastet auf 15 s, mit <kbd>Alt</kbd> auf 1 s). Kommt eine Kante bis auf wenige Pixel an einen Wegpunkt des Flights, an H oder an das Fenster eines anderen Flights, haftet sie dort (dünne blaue Linie); für feinere Arbeit hineinzoomen, <kbd>Alt</kbd> schaltet das Haften ab. H ziehen verschiebt das ganze Paket. Auf freier Fläche einen Bereich ziehen zoomt, Doppelklick zoomt zurück. Rechts oben wechselst du zwischen <strong>Aufträge</strong> (um die Fenster herum) und <strong>Ganze Routen</strong> (vom Start bis zur Landung).</p><h2 id="ein-flight-im-detail" tabindex="-1">Ein Flight im Detail <a class="header-anchor" href="#ein-flight-im-detail" aria-label="Permalink to &quot;Ein Flight im Detail&quot;">​</a></h2><p>Zeile anklicken, darunter erscheint:</p><ul><li><strong>Fenster</strong> und <strong>Push</strong> – Zeiten relativ zu H (<code>H-10</code>, <code>H+05:30</code>) oder als Uhrzeit in Ortszeit (<code>07:55</code>); gespeichert wird immer relativ zu H, H verschieben nimmt alles mit.</li><li><strong>Push-Punkt</strong> und <strong>Ziel-Punkt</strong> – Steerpoints der Route; bei Cartridges auch aus Route 2 und 3.</li><li><strong>Rückwärts geplant</strong> – <em>Anlassen 07:30 · Taxi 07:45 · Abheben 07:53 · Push 08:10 · Beginn 08:20</em>. Passt der Start im Mission Editor nicht, gibt es einen Hinweis. Bei <strong>Client-Slots</strong> startet der Pilot, wenn er einsteigt – Shardwing rechnet die Route ab diesem Start und warnt nur, wenn der Slot zu spät frei wird. Hat der Flight in seiner Cartridge TOS gesetzt, gelten diese: Der Start richtet sich nach dem ersten TOS, und die Matrix zeigt, wie weit die TOS vom Plan abweichen.</li><li><strong>Weitere Sollzeiten</strong> – z. B. <em>RV H−25</em> oder <em>IP H−03</em>, wahlweise mit Fenster und <strong>Ort</strong> (Koordinate; Rechtsklick auf die Karte kopiert eine). Mit Ort setzt der Flight seinen Steerpoint beim Zuordnen genau dorthin. Sie hängen an keinem Wegpunkt: Der Flight ordnet sie im <a href="./dtc#tos-rechner">TOS-Rechner</a> seinen Steerpoints zu. Darunter steht für jede Sollzeit, wo und wann die Route dort ist; Abweichungen erscheinen auch unter <em>Prüfungen</em>. Die Lineup Card zeigt bis zu drei davon in der Zeitleiste. Jede Sollzeit kann ein <strong>Band</strong> (FL von–bis) haben. Sollzeiten ohne Ort bleiben möglich. Umgekehrt macht <strong>Nur Ort</strong> aus einer Sollzeit einen Punkt ohne Zeit: Er erscheint nur in der DTC des Flights (TOS-Rechner) und wird im Timing weder gezeigt noch geprüft. Gibt es <a href="./zeichnungen#planungspunkte">Planungspunkte</a>, wählst du bei <strong>+ Sollzeit</strong> eine normale Sollzeit oder einen Punkt; der Flight wird dann dort eingetragen (2 min nach dem letzten Flight am Punkt). Gehört eine Sollzeit zu einem <a href="./zeichnungen#planungspunkte">Planungspunkt</a>, sind Name und Ort gesperrt (◆ öffnet den Punkt); eine Sollzeit mit Ort machst du mit <strong>◆ Als Planungspunkt</strong> zu einem.</li><li><strong>Höhenblock</strong> – z. B. FL200 bis FL220. Flights in getrennten Blöcken werden nicht gegeneinander geprüft.</li><li><strong>Tanken (AAR)</strong> – Slots beim Tanker buchen, siehe unten.</li><li><strong>Bemerkung</strong> – Freitext für die Unterlagen.</li><li><strong>Übertragen auf …</strong> – kopiert Teile dieses Flights einmalig auf andere: <em>Auftrag und Fenster</em>, <em>Push-Zeit</em>, <em>Sollzeiten und Treffpunkte</em>, <em>Höhenblock</em>, <em>AAR-Slots</em>, <em>Notiz</em>. Ziel-Flights ankreuzen, dazu <strong>Zeit je Flight +</strong> und <strong>Höhe je Flight +</strong>: Der erste bekommt +2 min und +2.000 ft, der zweite +4 min und +4.000 ft usw. Danach ist jeder Flight einzeln änderbar; Zeiten an Planungspunkten bleiben mit dem Punkt verbunden.</li></ul><h2 id="treffpunkte" tabindex="-1">Treffpunkte <a class="header-anchor" href="#treffpunkte" aria-label="Permalink to &quot;Treffpunkte&quot;">​</a></h2><p>Rechts unten stehen deine <a href="./zeichnungen#planungspunkte">Planungspunkte</a> mit allen Flights dort: Zeit, Fenster und Höhenband je Flight, dazu <em>Zeiten staffeln</em> und <em>Bänder stapeln</em>. Hier lässt sich alles einstellen, ohne zur Karte zu wechseln; <strong>Karte</strong> öffnet den Punkt in den Zeichnungen.</p><p>Die Dauern für <strong>Coldstart</strong>, <strong>Hotstart</strong> und <strong>Taxi</strong> stellst du links unter <em>Rückwärts bis zum Anlassen</em> ein (Standard 15, 2 und 8 Minuten).</p><h2 id="wegpunkte-mit-tos" tabindex="-1">Wegpunkte mit TOS <a class="header-anchor" href="#wegpunkte-mit-tos" aria-label="Permalink to &quot;Wegpunkte mit TOS&quot;">​</a></h2><p>Rechts unten die Route des gewählten Flights mit Höhe, Geschwindigkeit, <strong>TOS</strong> und Zeit relativ zu H; Push- und Zielpunkt sind markiert. Bei der Missionsroute sind Name, Höhe, Speed und TOS hier direkt änderbar – eine Zeit sperrt den Punkt wie ETA-Lock. Kommt die Route aus einer Cartridge, setzt du TOS im <a href="./dtc">DTC</a>. Die Spalte <strong>Soll</strong> zeigt die Sollzeiten an den Steerpoints, denen der Flight sie zugeordnet hat. Hat der Flight Push oder Ziel einem anderen Steerpoint zugeordnet als du, vergleicht die Matrix mit seinem; deine Auswahl bleibt gespeichert.</p><h2 id="tanker" tabindex="-1">Tanker <a class="header-anchor" href="#tanker" aria-label="Permalink to &quot;Tanker&quot;">​</a></h2><p>Tanker aus der Mission (Aufgabe <em>Refueling</em>) bekommen eine eigene Zeile mit Orbit-Fenster. Bei KI-Tankern mit Track ist das Fenster zugleich On und Off Track im <a href="./flights#zeitplan">Auftrag</a>; Off Track beendet dort den Orbit. Empfänger buchen ihren <strong>AAR-Slot</strong> in ihrer eigenen Zeile – vor dem Ziel, danach oder beides. Shardwing warnt bei:</p><ul><li><strong>Überbuchung</strong> des Tankers,</li><li>Slots <strong>außerhalb des Orbit-Fensters</strong>,</li><li><strong>Boom oder Drogue</strong> passt nicht – die F-16 braucht einen Boom, die F/A-18 einen Drogue (die KC-135 MPRS z. B. nur Drogue).</li></ul><h2 id="prufungen-und-deconfliction" tabindex="-1">Prüfungen und Deconfliction <a class="header-anchor" href="#prufungen-und-deconfliction" aria-label="Permalink to &quot;Prüfungen und Deconfliction&quot;">​</a></h2><p><strong>Prüfungen</strong> listet Timing-Konflikte: zu früh, zu spät, lange Wartezeit, Push-Abweichung.</p><p><strong>Deconfliction</strong> sucht Stellen, an denen sich zwei Routen laut Planung zu nahe kommen:</p><ul><li><strong>Konflikt, wenn näher als</strong> … NM und … ft (Standard 3 NM / 1.000 ft).</li><li><strong>Zielgebiet-Radius</strong> – ein Kreis um jeden geplanten Zielpunkt. Treffen sich zwei Flights darin, wird das nicht gemeldet: Über dem Ziel gelten die Absprachen der Piloten. 0 = überall prüfen.</li><li><strong>Treffpunkte</strong> – am selben Planungspunkt in getrennten Bändern ist kein Konflikt (Umkreis je nach Art, z. B. 5 NM am RV, 10 NM am Holding).</li><li>Anzeige für <strong>Paket</strong>, <strong>Gewählter</strong> Flight oder <strong>Alle</strong>. Konflikte zwischen Flights ohne Timing stehen nur als Zahl da („4 weitere“).</li><li>Einen Konflikt oder ein ganzes Paar kannst du <strong>für alle ausblenden</strong> – wird in der Planung gespeichert.</li></ul><h2 id="startzeit-der-mission" tabindex="-1">Startzeit der Mission <a class="header-anchor" href="#startzeit-der-mission" aria-label="Permalink to &quot;Startzeit der Mission&quot;">​</a></h2><p>Als Designer änderst du die Startzeit links unter dem Missionsnamen (<em>Start</em>); die Zeit aus dem Mission Editor steht in Klammern daneben. Sie wird beim Speichern in die .miz geschrieben. Alle Wegpunkt-Zeiten der Missionsroute zählen ab dem Start und wandern mit; H, Sollzeiten und die TOS der Cartridges bleiben, wo sie sind.</p>',27)])])}const b=n(a,[["render",d]]);export{c as __pageData,b as default};
